INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 16, 'theory', 'Quiz: shortest paths and spanning trees');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 16, 0, 'Why does Dijkstra not work with negative weights?', '["Because a heap does not support negative priorities", "Because negative weights are forbidden in navigation", "Greed relies on monotonicity: with negatives, a long path with a large negative part can turn out shorter, while the vertices are already closed", "Because a negative path always means a data error"]', 2, 'Dijkstra never revisits closed vertices. The practical takeaway: before applying it, ask whether the system has discounts, refunds, or negative delays.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 16, 1, 'What bonus makes Bellman-Ford indispensable?', '["It runs faster than Dijkstra on sparse graphs", "If estimates keep improving after n passes, a reachable negative cycle exists", "It does not need to keep the graph in memory", "It finds shortest paths between all pairs at once"]', 1, 'In a negative cycle the sum around the loop is negative, so a shortest path simply does not exist. The classic application is arbitrage chains in currency exchange rates.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 16, 2, 'When is A-star guaranteed to find the shortest path?', '["Always: the heuristic only speeds up the search", "When the heuristic is zero", "When the graph contains no cycles", "When the heuristic never overestimates the distance to the goal"]', 3, 'The search goes in order of "distance traveled plus heuristic" and is pulled toward the goal instead of exploring everything. An overestimating heuristic speeds things up even more, but breaks the guarantee.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 16, 3, 'How can one wave find the nearest of twenty pizzerias for every point on the map?', '["Put all sources into the heap with a zero estimate and run a single algorithm", "Run Dijkstra from each pizzeria and merge the results", "Build a minimum spanning tree of the road graph", "Sort all roads by length and go greedily"]', 0, 'Many sources is the same Dijkstra: the wave goes out from all sources at once, and every vertex learns its nearest one. A one-line modification makes the algorithm flexible.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 16, 4, 'Why is Kruskal''s greedy method provably optimal?', '["Because edges are sorted in n log n time", "Because the graph is always connected", "Because of the greedy-choice property and optimal substructure: the cheapest safe edge belongs to some minimum spanning tree", "Because the disjoint-set structure works in constant time"]', 2, 'Any other edge can be exchanged without making things worse. The general pattern: greed is optimal when the locally best step does not ruin the global optimum.');
